/**
 * Parity test: TS canonical rubric ↔ JS port shipped in the hook tarball.
 *
 * The port lives at scripts/hook-src/coznt-prompt-quality.mjs and is
 * generated by scripts/generate-hook-rubric.ts. This test imports both
 * implementations, runs a 20+ prompt corpus through each, and asserts
 * byte-identical output. If this test fails after a TS edit, re-run:
 *
 *     pnpm tsx scripts/generate-hook-rubric.ts
 *
 * and commit the regenerated .mjs. Always bump RUBRIC_VERSION on
 * algorithmic changes so server-side rescore-on-read picks up the drift.
 */

import { describe, expect, it } from "vitest";

import {
  RUBRIC_VERSION as TS_VERSION,
  scorePromptQuality as scoreTs,
} from "@/lib/prompt-quality/rubric";
import {
  RUBRIC_VERSION as JS_VERSION,
  scorePromptQuality as scoreJs,
} from "../scripts/hook-src/coznt-prompt-quality.mjs";

const CORPUS: Array<{ name: string; content: string; phase?: string | null }> = [
  { name: "empty", content: "" },
  { name: "halp", content: "halp" },
  { name: "vague-fix-it", content: "fix it" },
  { name: "vague-make-this-work", content: "make this work" },
  { name: "single-action-verb", content: "Add tests" },
  { name: "short-with-file", content: "Update src/lib/foo.ts" },
  { name: "single-context-signal", content: "Refactor because the build is flaky" },
  {
    name: "well-formed-development",
    content:
      "Add idempotency to src/app/api/v1/payments/route.ts because retries are double-charging customers. Must preserve the response shape and avoid breaking changes. Issue #482.",
    phase: "development",
  },
  {
    name: "deploy-in-development",
    content: "Deploy this to production immediately",
    phase: "development",
  },
  {
    name: "deploy-in-cicd-allowed",
    content: "Deploy the release pipeline to production",
    phase: "cicd",
  },
  {
    name: "phase-aligned-requirements",
    content: "Draft a user story for the new candidate dashboard requirement",
    phase: "requirements",
  },
  {
    name: "phase-aligned-design",
    content: "Write an ADR documenting the schema for the audit log architecture",
    phase: "design",
  },
  {
    name: "phase-aligned-testing",
    content: "Add a test case covering the fixture for empty input assert paths",
    phase: "testing",
  },
  {
    name: "phase-aligned-monitoring",
    content: "Set up a monitor alert dashboard SLO for incident detection",
    phase: "monitoring",
  },
  {
    name: "secret-openai",
    content: "Use this token to fix the call: sk-abcdefghijklmnopqrstuvwx1234567890",
  },
  {
    name: "secret-bearer",
    content:
      "Curl with Authorization: Bearer abcdef0123456789abcdef0123456789 to validate",
  },
  {
    name: "secret-github",
    content: "Push using ghp_abcdefghijklmnopqrstuvwxyz1234567890",
  },
  {
    name: "secret-aws",
    content: "AWS access key AKIAABCDEFGHIJKLMNOP",
  },
  {
    name: "secret-password",
    content: "Connect with password: hunter22hunter22",
  },
  {
    name: "code-fence-prompt",
    content:
      "Implement this in src/lib/util.ts:\n```ts\nexport function add(a: number, b: number) { return a + b; }\n```\nMust handle negatives.",
    phase: "development",
  },
  {
    name: "constraints-heavy",
    content:
      "Refactor the storage layer. Must preserve existing API shape. Do not introduce breaking changes. Only touch src/lib/storage.ts.",
    phase: "development",
  },
  {
    name: "unicode-and-emoji",
    content: "Refactor src/app/page.tsx so the héading uses a different style 🚀",
    phase: "development",
  },
];

describe("rubric parity: TS canonical ↔ .mjs port", () => {
  it("rubric versions match", () => {
    expect(JS_VERSION).toBe(TS_VERSION);
  });

  it.each(CORPUS)("$name → byte-identical score", ({ content, phase }) => {
    const ts = scoreTs({ content, phase: (phase ?? null) as never });
    const js = scoreJs({ content, phase: phase ?? null });

    expect(js.overallScore).toBe(ts.overallScore);
    expect(js.tier).toBe(ts.tier);
    expect(js.dimensions).toEqual(ts.dimensions);
    expect(js.suggestions).toEqual(ts.suggestions);
    expect(js.flags).toEqual(ts.flags);
    expect(js.rubricVersion).toBe(ts.rubricVersion);
  });
});
